"""Compact Qt controls using the desktop's generated palettes and saved theme."""

import json
from functools import lru_cache
from pathlib import Path

from PyQt6.QtCore import QEvent, QObject, QTimer
from PyQt6.QtGui import QColor, QPalette
from PyQt6.QtWidgets import QWidget

DEFAULT_THEME = "gsm-dark"


@lru_cache(maxsize=1)
def _palettes() -> dict[str, dict[str, str]]:
    # Generated by npm run sync:theme and included by the assets/* package rule.
    source = Path(__file__).resolve().parents[1] / "assets" / "qt_themes.json"
    return json.loads(source.read_text(encoding="utf-8"))


def get_theme_palette(theme: str = DEFAULT_THEME) -> dict[str, str]:
    palettes = _palettes()
    return palettes.get(theme, palettes[DEFAULT_THEME])


