@lru_cache(maxsize=48)
def _stylesheet(theme: str) -> str:
    colors = get_theme_palette(theme)
    import qdarktheme

    # Generate matching light/dark icons and checkbox assets for this window.
    base = qdarktheme.load_stylesheet(
        theme=colors["scheme"],
        custom_colors={
            "background": colors["surface-0"],
            "foreground": colors["text-primary"],
            "primary": colors["accent"],
            "border": colors["border-default"],
        },
    )
    sheet = _STYLESHEET
    for key, value in colors.items():
        sheet = sheet.replace(f"@{key}@", value)
    return base + sheet


def _status_css(colors: dict[str, str], tone: str, boxed: bool) -> str:
    color = colors.get(f"{tone}-text", colors.get(f"text-{tone}", colors["text-primary"]))
    if boxed:
        return (
            f"color: {color}; background: {colors[tone + '-soft']}; "
            f"border: 1px solid {colors[tone + '-border']}; border-radius: 5px; padding: 7px;"
        )
    return f"color: {color};"


def set_status_style(widget: QWidget, tone: str, *, boxed: bool = False) -> None:
    """Track semantic status colors so they also refresh on a theme change."""
    if isinstance(widget, QWidget):
        widget.setProperty("gsmStatusTone", tone)
        widget.setProperty("gsmStatusBoxed", boxed)
        colors = get_theme_palette(widget.window().property("gsmTheme") or DEFAULT_THEME)
    else:
        colors = get_theme_palette()
    widget.setStyleSheet(_status_css(colors, tone, boxed) if tone else "")


class _DesktopThemeController(QObject):
    def __init__(self, window: QWidget, config_path: Path):
        super().__init__(window)
        self.window = window
        self.config_path = config_path
        self.theme = ""
        self.timer = QTimer(self)
        self.timer.setInterval(1000)
        self.timer.timeout.connect(self.refresh)
        window.installEventFilter(self)
        self.refresh()

    def refresh(self, *, force: bool = False) -> None:
        try:
            saved = json.loads(self.config_path.read_text(encoding="utf-8"))
            selected = saved.get("theme", DEFAULT_THEME) if isinstance(saved, dict) else DEFAULT_THEME
        except FileNotFoundError:
            selected = DEFAULT_THEME
        except (OSError, ValueError):
            if self.theme:
                return
            selected = DEFAULT_THEME
        colors = get_theme_palette(selected if isinstance(selected, str) else DEFAULT_THEME)
        if self.theme == colors["id"] and not force:
            return
        self.theme = colors["id"]
        self.window.setProperty("gsmTheme", self.theme)
        palette = self.window.palette()
        for role, key in (
            (QPalette.ColorRole.Window, "surface-0"),
            (QPalette.ColorRole.WindowText, "text-primary"),
            (QPalette.ColorRole.Base, "surface-1"),
            (QPalette.ColorRole.AlternateBase, "surface-0"),
            (QPalette.ColorRole.Text, "text-primary"),
            (QPalette.ColorRole.Button, "surface-1"),
            (QPalette.ColorRole.ButtonText, "text-primary"),
            (QPalette.ColorRole.Highlight, "accent"),
            (QPalette.ColorRole.HighlightedText, "on-accent-dark"),
            (QPalette.ColorRole.PlaceholderText, "text-muted"),
        ):
            palette.setColor(role, QColor(colors[key]))
        palette.setColor(QPalette.ColorGroup.Disabled, QPalette.ColorRole.Text, QColor(colors["text-faint"]))
        self.window.setPalette(palette)
        self.window.setStyleSheet(_stylesheet(self.theme))
        from GameSentenceMiner.ui.config.labels import LABEL_COLOR_TOKENS

        for child in self.window.findChildren(QWidget):
            tone = child.property("gsmStatusTone")
            if tone:
                child.setStyleSheet(_status_css(colors, tone, bool(child.property("gsmStatusBoxed"))))
            label_color = child.property("gsmLabelColor")
            if label_color in LABEL_COLOR_TOKENS:
                style = f"color: {colors[LABEL_COLOR_TOKENS[label_color]]};"
                if child.property("gsmLabelBold"):
                    style += " font-weight: bold;"
                child.setStyleSheet(style)
        from GameSentenceMiner.ui.audio_waveform_widget import AudioWaveformWidget

        for waveform in self.window.findChildren(AudioWaveformWidget):
            cut_color = QColor(colors["danger"])
            cut_color.setAlpha(155)
            waveform.color_cut = cut_color
            waveform.color_cut_border = QColor(colors["danger-text"])
            waveform.set_colors(
                {
                    "background": colors["surface-0"],
                    "waveform_unselected": colors["text-faint"],
                    "waveform_selected": colors["accent"],
                    "handle": colors["accent"],
                    "handle_hover": colors["accent-strong"],
                    "cursor": colors["danger-text"],
                    "border": colors["border-default"],
                }
            )
            waveform.expand_start_button.setStyleSheet("")
            waveform.expand_end_button.setStyleSheet("")
            waveform.range_chip.setStyleSheet(
                f"color: {colors['text-primary']}; background: {colors['surface-1']}; "
                f"border: 1px solid {colors['border-default']}; border-radius: 4px; padding: 1px 6px;"
            )

    def eventFilter(self, watched, event):
        if event.type() in (QEvent.Type.Show, QEvent.Type.WindowActivate):
            self.refresh(force=event.type() == QEvent.Type.Show)
            self.timer.start()
        elif event.type() == QEvent.Type.Hide:
            self.timer.stop()
        return False


def apply_compact_theme(window: QWidget, *, config_path: Path | None = None) -> None:
    """Follow the desktop preference while preserving compact native layouts."""
    if getattr(window, "_gsm_theme_controller", None) is not None:
        return
    if config_path is None:
        from GameSentenceMiner.util.config.configuration import get_app_directory

        config_path = Path(get_app_directory()) / "electron" / "config.json"
    window.setProperty("compactWindow", True)
    window._gsm_theme_controller = _DesktopThemeController(window, config_path)
